local config = {
  ui_story_5041_50410101_1_dialog_content = "Luke, ada paket untukmu!",
  ui_story_5041_50410101_2_dialog_content = "PlayerName? Mengapa Anda memberikan?",
  ui_story_5041_50410101_3_dialog_content = "Dan siapa ini?",
  ui_story_5041_50410101_4_dialog_content = "Ini Lady Jeriah dari Courier Union. Saya hanya membantu untuk Hari Mahkota Bulan.",
  ui_story_5041_50410101_5_dialog_content = "Halo, Wakil Komandan Tentara Bayaran Api Putih. Reputasi Anda mendahului Anda.",
  ui_story_5041_50410101_6_dialog_content = "Seorang anggota senior Serikat Kurir? Suatu kehormatan bertemu dengan Anda. Tapi siapa yang akan mengirimiku paket?",
  ui_story_5041_50410101_7_dialog_content = "Mengapa Anda tidak membukanya? Haruskah kami memberi Anda privasi?",
  ui_story_5041_50410101_8_dialog_content = "Tidak dibutuhkan. Jika ternyata itu adalah ancaman dari musuh bebuyutan, saya memerlukan info lebih lanjut dari Anda.",
  ui_story_5041_50410101_9_dialog_content = "Bukankah kamu terlalu berhati-hati? Pengemasan lembut seperti itu tidak mungkin berasal dari saingan.",
  ui_story_5041_50410101_10_dialog_content = "Hmm, ada catatan terlampir di dalam kotak.",
  ui_story_5041_50410101_11_dialog_content = "\"Komandan Luke, maaf berkomunikasi denganmu seperti ini, tetapi misinya didahulukan, jadi kita harus mengandalkan korespondensi.\"",
  ui_story_5041_50410101_12_dialog_content = "\"Kami semua telah menyaksikan secara langsung rasa tanggung jawabmu kepada Tentara Bayaran Api Putih dan pertimbangan untuk semua orang.\"",
  ui_story_5041_50410101_13_dialog_content = "\"Yang kami lakukan hanyalah menjalankan misi, tetapi Anda harus memikirkan masa depan organisasi dan bagaimana mengembangkannya...\"",
  ui_story_5041_50410101_14_dialog_content = "\"Kamu juga memperhatikan kesejahteraan setiap anggota sampai ke detail terkecil. Kami sering bercanda dan mengatakan kamu mahakuasa.\"",
  ui_story_5041_50410101_15_dialog_content = "\"Namun, aku tahu kamu juga orang normal, dan membebani begitu banyak waktu membuatmu lelah.\"",
  ui_story_5041_50410101_16_dialog_content = "Ini dari mereka... Aku bilang pada mereka untuk tidak memanggilku \"komandan\". Tidak percaya mereka meluangkan waktu untuk menulis ini di tengah misi.",
  ui_story_5041_50410101_17_dialog_content = "Itu sangat menyentuh. Saya kira tentara bayaran Anda sangat peduli dengan Anda.",
  ui_story_5041_50410101_18_dialog_content = "Itu karena Luke adalah orang yang sangat bertanggung jawab, sebuah fakta yang jelas bagi semua orang.",
  ui_story_5041_50410101_19_dialog_content = "Apa lagi isi surat itu?",
  ui_story_5041_50410101_20_dialog_content = "\"Kamu bangun pagi dan tidur larut malam setiap malam, jadi kami meluangkan waktu untuk membuatkanmu kantong herbal.\"",
  ui_story_5041_50410101_21_dialog_content = "\"Kami mendengar ramuan ini dapat membantu tidur. Silakan mencobanya lain kali saat Anda tidur dengan meletakkannya di samping bantal Anda.\"",
  ui_story_5041_50410101_22_dialog_content = "\"Kami harap kamu juga bisa tidur siang sesekali.\"",
  ui_story_5041_50410101_23_dialog_content = "\"Dari, Tentara Bayaranmu.\"",
  ui_story_5041_50410101_24_dialog_content = "Melakukan semua ini dalam sebuah misi... Aku hanya melakukan apa yang seharusnya kulakukan, sungguh.",
  ui_story_5041_50410101_25_dialog_content = "Saya tentu tidak mengharapkan ini.",
  ui_story_5041_50410101_26_dialog_content = "Ya, Luke, sesekali kau harus tenang. Anda rentan terhadap kesalahan jika Anda selalu tegang seperti kawat.",
  ui_story_5041_50410101_27_dialog_content = "Istirahat yang tepat sangat penting untuk menyelesaikan setiap tugas baru yang menghampiri kita... Saya pikir mereka benar.",
  ui_story_5041_50410101_28_dialog_content = "Karena semua orang tampaknya mengatakan hal yang sama, saya akan menerima sarannya.",
  ui_story_5041_50410101_29_dialog_content = "Setelah saya selesai hari ini, saya akan tidur siang dengan kantong di sebelah bantal saya.",
  ui_story_5041_50410201_1_dialog_content = "Huff, huff... Itu dia, Komandan Hiiro!",
  ui_story_5041_50410201_2_dialog_content = "PlayerName?",
  ui_story_5041_50410201_3_dialog_content = "Apa yang kamu lakukan di sini? Apakah sesuatu terjadi di Illumina?!",
  ui_story_5041_50410201_4_dialog_content = "Tidak, saya hanya mengirimkan surat dengan Jeriah dari Courier Union. Ini, paket untukmu, yang cukup besar juga.",
  ui_story_5041_50410201_5_dialog_content = "Heh, saya pikir pengirimnya menarik.",
  ui_story_5041_50410201_6_dialog_content = "Aneh, siapa yang akan mengirimkan paket kepadaku jauh-jauh ke sini di garis depan?",
  ui_story_5041_50410201_7_dialog_content = "Itu normal. Lagipula ini Hari Mooncrown.",
  ui_story_5041_50410201_8_dialog_content = "Hari Mahkota Bulan? Ah, benar... Aku benar-benar lupa.",
  ui_story_5041_50410201_9_dialog_content = "Saya terdesak waktu, jadi mari kita lihat apa yang ada di dalamnya... Tunggu, biarkan saya melihat siapa yang mengirimkannya terlebih dahulu.",
  ui_story_5041_50410201_10_dialog_content = "Oh, ini dari Zoya. Ini adalah...",
  ui_story_5041_50410201_11_dialog_content = "Roti serbuk gergaji, daging kalengan, krim sup jamur, kacang cokelat, dan bahkan roti gulung kayu manis.",
  ui_story_5041_50410201_12_dialog_content = "Itu semua spesialisasi Illumina.",
  ui_story_5041_50410201_13_dialog_content = "Saya percaya itu adalah tradisi bagi pecinta di Illumina untuk memberi hadiah gulungan kayu manis buatan tangan. Sangat romantis.",
  ui_story_5041_50410201_14_dialog_content = "Itu mungkin tidak disengaja dari pihak Zoya.",
  ui_story_5041_50410201_15_dialog_content = "(Entah bagaimana, saya tidak berpikir itu tidak disengaja.)",
  ui_story_5041_50410201_16_dialog_content = "Saya pikir ada tulisan di kotaknya.",
  ui_story_5041_50410201_17_dialog_content = "\"Lady Hiiro, terima kasih atas pekerjaanmu di garis depan! Aku dengar kamu akan pergi lama kali ini. Aku hanya bisa membayangkan betapa melelahkannya itu.\"",
  ui_story_5041_50410201_18_dialog_content = "\"Aku membayangkan kamu akan mendambakan makanan lezat Illumina, jadi aku meminta Gram untuk menyiapkan paket perawatan.\"",
  ui_story_5041_50410201_19_dialog_content = "\"Tapi saya memang membuat gulungan kayu manis sendiri, jadi pastikan Anda mencicipinya dulu!\"",
  ui_story_5041_50410201_20_dialog_content = "(Saya bisa membayangkan raut wajah Zoya.)",
  ui_story_5041_50410201_21_dialog_content = "\"Lady Hiiro, aku ingin menghabiskan Hari Mahkota Bulan bersamamu, tapi garis depan adalah prioritas, jadi tolong jaga dirimu!\"",
  ui_story_5041_50410201_22_dialog_content = "\"Hati dan jiwaku adalah milikmu, Nona Hiiro yang cantik, kuat, dan keren!\"",
  ui_story_5041_50410201_23_dialog_content = "Seseorang yang bisa membaca kalimat seperti itu dengan lantang dengan wajah datar sungguh luar biasa.",
  ui_story_5041_50410201_24_dialog_content = "Ahaha, saya setuju.",
  ui_story_5041_50410201_25_dialog_content = "Saya sangat menghargai pemikiran Zoya, dan saya pasti merindukan makanan Illumina.",
  ui_story_5041_50410201_26_dialog_content = "Dia selalu begitu perhatian. Saya yakin semua orang di lab penelitian menyukainya juga.",
  ui_story_5041_50410201_27_dialog_content = "Aku pikir dia hanya peduli padamu...",
  ui_story_5041_50410201_28_dialog_content = "Karena dia membuat gulungan kayu manis sendiri, saya akan menggigitnya.",
  ui_story_5041_50410201_29_dialog_content = "*mengunyah*",
  ui_story_5041_50410201_30_dialog_content = "Mm. Saya benar-benar bisa merasakan perasaan Zoya dari ini.",
  ui_story_5041_50410201_31_dialog_content = "(Saya berani menebak rasanya sangat dipertanyakan...)",
  ui_story_5041_50410201_32_dialog_content = "Terima kasih telah mengantarkan ini ke garis depan. Kenapa kalian berdua tidak menginap? Kita bisa menikmati makanan ini bersama-sama.",
  ui_story_5041_50410201_33_dialog_content = "Tentu, saya cukup tertarik dengan tarif Illumina.",
  ui_story_5041_50410201_34_dialog_content = "Hei, kami masih memiliki lebih banyak surat untuk dikirimkan!",
  ui_story_5041_50410301_1_dialog_content = "Novio, aku punya paket untukmu!",
  ui_story_5041_50410301_2_dialog_content = "Kami pergi ke Istana Musim Dingin terlebih dahulu, tetapi yang mengejutkan, Anda tidak ada di sana.",
  ui_story_5041_50410301_3_dialog_content = "Aku hanya di sini berjalan-jalan. Saya tidak berharap Anda menjadi kurir, PlayerName.",
  ui_story_5041_50410301_4_dialog_content = "Saya datang dengan Jeriah, jadi saya benar-benar hanya membantu.",
  ui_story_5041_50410301_5_dialog_content = "Pemandangan di Northland selalu spektakuler, tidak peduli sudah berapa kali saya ke sini.",
  ui_story_5041_50410301_6_dialog_content = "Itu terpencil dari sisa benua, hampir di dunianya sendiri. Saya harap Anda suka di sini.",
  ui_story_5041_50410301_7_dialog_content = "Oh ya, ini paketmu. Ini dari Lola!",
  ui_story_5041_50410301_8_dialog_content = "Lola? Jika saya ingat dengan benar, dia belum berada di Northland akhir-akhir ini.",
  ui_story_5041_50410301_9_dialog_content = "Dia tampaknya telah mengunjungi banyak tempat. Pipinya merah karena kegembiraan.",
  ui_story_5041_50410301_10_dialog_content = "Mengingat kepribadiannya, dia mungkin bersenang-senang menikmati camilan dan pernak-pernik lokal.",
  ui_story_5041_50410301_11_dialog_content = "Bagaimanapun, biarkan aku melihat ke dalam ...",
  ui_story_5041_50410301_12_dialog_content = "Cokelat berbentuk seperti Eclipsites?",
  ui_story_5041_50410301_13_dialog_content = "Itu terlihat cantik... asli.",
  ui_story_5041_50410301_14_dialog_content = "Ada catatan juga.",
  ui_story_5041_50410301_15_dialog_content = "\"Novio, lihat cokelat rasa Eclipsite yang kutemukan di toko permen Umbraton. Kamu harus mencobanya!\"",
  ui_story_5041_50410301_16_dialog_content = "Saya kesulitan membayangkan bagaimana rasanya Eclipsites.",
  ui_story_5041_50410301_17_dialog_content = "Yah, selalu ada yang pertama untuk segalanya.",
  ui_story_5041_50410301_18_dialog_content = "Dan apa yang ada di dalam kotak hitam ini... Whoa!",
  ui_story_5041_50410301_19_dialog_content = "A-Apakah kamu baik-baik saja, Novio?",
  ui_story_5041_50410301_20_dialog_content = "Apakah ini salah satu mainan jack-in-the-box? Itu membuatku takut.",
  ui_story_5041_50410301_21_dialog_content = "Kepala ini sedikit mengingatkan seseorang ...",
  ui_story_5041_50410301_22_dialog_content = "Apakah hanya saya, atau terlihat seperti Sinsa?",
  ui_story_5041_50410301_23_dialog_content = "Ini desain yang menyenangkan, tapi saya harus menyimpannya.",
  ui_story_5041_50410301_24_dialog_content = "\"Berlari ke pelelangan di pasar gurun dan tidak percaya tidak ada yang menawar mainan keren ini, jadi saya membelinya!\"",
  ui_story_5041_50410301_25_dialog_content = "\"Saya pikir itu meniru seseorang, tapi tidak tahu siapa.\"",
  ui_story_5041_50410301_26_dialog_content = "Saya bahkan tidak tahu pasar itu menjual barang-barang ini. Unik sekali.",
  ui_story_5041_50410301_27_dialog_content = "Itu memang cocok dengan gaya Lola.",
  ui_story_5041_50410301_28_dialog_content = "Semoga tidak ada lagi kejutan di kotak ini... Apakah ini bunga kering?",
  ui_story_5041_50410301_29_dialog_content = "Mereka sangat cantik...",
  ui_story_5041_50410301_30_dialog_content = "\"Saya mengumpulkan ini selama perjalanan saya. Itu termasuk mawar liar favorit saya, dan beberapa lainnya saya tidak kenal.\"",
  ui_story_5041_50410301_31_dialog_content = "\"Saya menekannya ke bookmark. Anda suka membaca jadi saya pikir Anda akan menganggapnya berguna!\"",
  ui_story_5041_50410301_32_dialog_content = "\"Jika kamu tahu bunga apa itu, beri tahu aku!\"",
  ui_story_5041_50410301_33_dialog_content = "Dia benar-benar berjiwa bebas... Dan semua bunganya menakjubkan.",
  ui_story_5041_50410301_34_dialog_content = "Saya percaya ini adalah bayam, palm lily, dan melati. Saya kira saya harus menulis kembali dan memberitahunya.",
  ui_story_5041_50410301_35_dialog_content = "Terima kasih banyak atas pengiriman paketnya. Apakah Anda ingin mencoba cokelat dengan saya?",
  ui_story_5041_50410301_36_dialog_content = "(Cokelat rasa Eclipse? Saya pikir saya akan lulus.)",
  ui_story_5041_50410301_37_dialog_content = "Terima kasih banyak.",
  ui_story_5041_50410301_38_dialog_content = "Hei, jangan sembarang makan!",
  ui_story_5041_50410401_1_dialog_content = "Ini seharusnya alamatnya... mungkin?",
  ui_story_5041_50410401_2_dialog_content = "Tulisannya sangat tidak terbaca, hampir sakit mata saya untuk membacanya!",
  ui_story_5041_50410401_3_dialog_content = "Aku hampir tidak bisa mengatakan itu dialamatkan ke Harbour City, tapi sisanya berantakan...",
  ui_story_5041_50410401_4_dialog_content = "Apakah kita bahkan di tempat yang tepat?",
  ui_story_5041_50410401_5_dialog_content = "Ya, ini adalah tempat yang tepat.",
  ui_story_5041_50410401_6_dialog_content = "Bagaimana kau begitu yakin, Jeriah?",
  ui_story_5041_50410401_7_dialog_content = "Lihat ke sana, bukankah orang itu terlihat seperti sedang menunggu surat?",
  ui_story_5041_50410401_8_dialog_content = "Sigh, apakah itu akan ada di sini hari ini? aku agak lelah...",
  ui_story_5041_50410401_9_dialog_content = "Kapan di dunia dia sampai di sana ?! Saya tidak melihatnya di sana sebelumnya!",
  ui_story_5041_50410401_10_dialog_content = "Apa yang kaumaksud itu aku?",
  ui_story_5041_50410401_11_dialog_content = "Saya sudah di sini selama ini, tetapi belum pindah karena saya terlalu lelah.",
  ui_story_5041_50410401_12_dialog_content = "Tidak heran aku tidak melihatmu...",
  ui_story_5041_50410401_13_dialog_content = "Apakah Anda kurir?",
  ui_story_5041_50410401_14_dialog_content = "Ya, kami, nona muda.",
  ui_story_5041_50410401_15_dialog_content = "Ini ditujukan kepada Ni... Nina?",
  ui_story_5041_50410401_16_dialog_content = "Itu Tina. Teh, na.",
  ui_story_5041_50410401_17_dialog_content = "Jangan bilang kau lupa namaku?",
  ui_story_5041_50410401_18_option_content = "Aku tahu kamu!",
  ui_story_5041_50410401_19_dialog_content = "Anda yang ingin mendapatkan perangko dari Jeriah di Lumopolis, bukan?",
  ui_story_5041_50410401_20_dialog_content = "Anda ingat saya.",
  ui_story_5041_50410401_21_dialog_content = "Tentu saja, saya memiliki pikiran seperti jebakan baja.",
  ui_story_5041_50410401_22_option_content = "Aku tidak yakin...",
  ui_story_5041_50410401_23_dialog_content = "Lalu izinkan saya memperkenalkan diri.",
  ui_story_5041_50410401_24_dialog_content = "Saya Hakim Tina dari Balai Kehakiman di Lumopolis. Saya di Harbour City sekarang untuk urusan resmi.",
  ui_story_5041_50410401_25_dialog_content = "Bolehkah saya bertanya apakah ini untuk saya?",
  ui_story_5041_50410401_26_dialog_content = "Memang terlihat bahwa nama penerimanya adalah Tina.",
  ui_story_5041_50410401_27_dialog_content = "Maaf, tulisannya terlalu sulit untuk dibuat.",
  ui_story_5041_50410401_28_dialog_content = "Saya tidak berharap melihat seseorang dari Lumo Hall of Justice di Harbour City.",
  ui_story_5041_50410401_29_dialog_content = "Itu adalah perjalanan yang panjang, tetapi tidur di pesawat adalah pengalaman yang cukup.",
  ui_story_5041_50410401_30_dialog_content = "Kapal itu bergoyang lembut tertiup angin, dan ranjang empuknya seperti buaian.",
  ui_story_5041_50410401_31_dialog_content = "Aku tahu perasaan itu! Ini seperti ketika saya pergi tidur di Colossus saat berada di udara.",
  ui_story_5041_50410401_32_dialog_content = "Kamu punya selera yang bagus.",
  ui_story_5041_50410401_33_dialog_content = "Dilihat dari pakaianmu, kamu pasti orang yang mereka sebut Navigator of the Colossus? Caelestite Terakhir?",
  ui_story_5041_50410401_34_dialog_content = "Er... judul saya sepertinya semakin menarik...",
  ui_story_5041_50410401_35_dialog_content = "Mengapa saya tidak memperkenalkan diri saja?",
  ui_story_5041_50410401_36_dialog_content = "Aku memang Caelestite, tapi hanya Caelestite biasa.",
  ui_story_5041_50410401_37_dialog_content = "Telepon saya saja PlayerName!",
  ui_story_5041_50410401_38_dialog_content = "PlayerName? Hmm, nama yang menarik.",
  ui_story_5041_50410401_39_dialog_content = "Saya membantu Serikat Kurir mengirimkan surat sekarang. Dengan saya di sini adalah Jeriah.",
  ui_story_5041_50410401_40_dialog_content = "Halo!",
  ui_story_5041_50410401_41_dialog_content = "Kamu wanita muda yang menggemaskan.",
  ui_story_5041_50410401_42_dialog_content = "Bagaimanapun, tolong tanda tangani di sini!",
  ui_story_5041_50410401_43_dialog_content = "Hmm, mungkinkah ini \"itu\"...?",
  ui_story_5041_50410401_44_dialog_content = "<color=#e8d9bb>*tanda*</color>",
  ui_story_5041_50410401_45_dialog_content = "\"Itu\"?",
  ui_story_5041_50410401_46_dialog_content = "Sesuatu yang saya tunggu-tunggu selama ini, sejak saya menulis surat kepada orang itu.",
  ui_story_5041_50410401_47_dialog_content = "Baiklah, biarkan aku mencari tahu dengan pasti ...",
  ui_story_5041_50410401_48_dialog_content = "<color=#e8d9bb>Meninggal dunia-</color>",
  ui_story_5041_50410401_49_dialog_content = "Hah?",
  ui_story_5041_50410401_50_dialog_content = "Hmm…",
  ui_story_5041_50410401_51_dialog_content = "Sekantong daun? Dan dua buah liar yang mungkin bisa dimakan atau tidak...",
  ui_story_5041_50410401_52_dialog_content = "T-Daunnya busuk... Mereka tidak rusak dalam perjalanan, kan?",
  ui_story_5041_50410401_53_dialog_content = "PlayerName, apakah Anda memeriksa kondisi paket saat Anda menerimanya?",
  ui_story_5041_50410401_54_dialog_content = "Tidak...",
  ui_story_5041_50410401_55_dialog_content = "Saya melihat paket ini di pintu saya ketika saya pergi pagi ini.",
  ui_story_5041_50410401_56_dialog_content = "Ketika saya melihat dan melihat bahwa itu bukan untuk saya, saya memperlakukannya seperti paket yang menunggu pengiriman dan membawanya bersama saya.",
  ui_story_5041_50410401_57_dialog_content = "Bukan begitu cara kerjanya, Caelestite.",
  ui_story_5041_50410401_58_dialog_content = "Anda harus memeriksa kondisi isi saat menerima paket sehingga Anda tahu tindakan pencegahan apa yang diperlukan untuk mengirimkannya.",
  ui_story_5041_50410401_59_dialog_content = "Ini adalah bagian dasar dari menjadi seorang kurir.",
  ui_story_5041_50410401_60_dialog_content = "Maaf...",
  ui_story_5041_50410401_61_dialog_content = "Eh, apa yang kamu bicarakan?",
  ui_story_5041_50410401_62_dialog_content = "Daun ini tidak rusak.",
  ui_story_5041_50410401_63_dialog_content = "Mereka tidak?",
  ui_story_5041_50410401_64_dialog_content = "Lihat ini di daun? Bukankah itu menyerupai Universese?",
  ui_story_5041_50410401_65_dialog_content = "Ya, sekarang setelah Anda menyebutkannya!",
  ui_story_5041_50410401_66_dialog_content = "Tapi itu sangat bengkok, saya hampir tidak mengenalinya.",
  ui_story_5041_50410401_67_dialog_content = "Saya pikir itu berbunyi, \"Terima kasih\"?",
  ui_story_5041_50410401_68_dialog_content = "Ini bukan daun biasa. Itu kertas surat.",
  ui_story_5041_50410401_69_dialog_content = "Meskipun saya sangat gembira mendapatkan ini, itu sangat disayangkan.",
  ui_story_5041_50410401_70_dialog_content = "Daunnya dalam urutan acak dan tulisannya tidak mungkin diuraikan ...",
  ui_story_5041_50410401_71_dialog_content = "Bahkan aku tidak bisa menguraikan semuanya pada mereka ...",
  ui_story_5041_50410401_72_dialog_content = "Sangat menyedihkan bahwa saya tidak akan mengetahui apa yang ingin dikatakan oleh teman kecil itu.",
  ui_story_5041_50410401_73_dialog_content = "Tapi rasanya senang mendapat balasan.",
  ui_story_5041_50410401_74_dialog_content = "Terima kasih keduanya telah mengirimkannya.",
  ui_story_5041_50410401_75_dialog_content = "Siapa anak kecil yang terus kau bicarakan?",
  ui_story_5041_50410401_76_dialog_content = "Kedengarannya seperti adik laki-laki atau perempuan.",
  ui_story_5041_50410401_77_dialog_content = "Ya, Anda bisa menyebut mereka begitu.",
  ui_story_5041_50410401_78_dialog_content = "Orang itu semanis anak kucing dan membuat Anda ingin memeluknya.",
  ui_story_5041_50410401_79_dialog_content = "Apakah itu binatang kecil?",
  ui_story_5041_50410401_80_dialog_content = "Ini sebuah rahasia.",
  ui_story_5041_50410401_81_dialog_content = "Baiklah, aku tidak akan mengorek. Lagipula, Anda berhak atas privasi Anda.",
  ui_story_5041_50410401_82_dialog_content = "Terima kasih telah memilih Serikat Kurir. Menantikan untuk melayani Anda lain kali!",
  ui_story_5041_50410401_83_dialog_content = "Pastikan untuk mengkonfirmasi kondisi paket apa pun yang Anda kirimkan juga.",
  ui_story_5041_50410401_84_dialog_content = "Ya…",
  ui_story_5041_50410501_1_dialog_content = "Ini dia, Hawa!",
  ui_story_5041_50410501_2_dialog_content = "Itu kamu, PlayerName! Dan siapa ini?",
  ui_story_5041_50410501_3_dialog_content = "Halo nona muda, saya Jeriah dari Courier Union.",
  ui_story_5041_50410501_4_dialog_content = "Oh, seorang kurir. Saya belum pernah melihat siapa pun dari Union sebelumnya.",
  ui_story_5041_50410501_5_dialog_content = "Halo, saya Hawa!",
  ui_story_5041_50410501_6_dialog_content = "Anda mendapat surat, Eve!",
  ui_story_5041_50410501_7_dialog_content = "Ini dari Sinsa.",
  ui_story_5041_50410501_8_dialog_content = "Abang saya? Aku ingin tahu apa yang dia kirimkan padaku.",
  ui_story_5041_50410501_9_dialog_content = "Mungkin sesuatu yang sangat penting.",
  ui_story_5041_50410501_10_dialog_content = "Inilah yang dia katakan ketika dia menyerahkan paket itu kepada kami ...",
  ui_story_5041_50410501_11_dialog_content = "Ini adalah pengiriman mendesak untuk Hawa. Pastikan dia mendapatkannya! Mengerti?",
  ui_story_5041_50410501_12_dialog_content = "Ba-baik!",
  ui_story_5041_50410501_13_dialog_content = "Ini pertama kalinya dia jauh dari rumah sendirian. Saya harus memastikan keselamatannya dan menjauhkannya dari orang jahat.",
  ui_story_5041_50410501_14_dialog_content = "Aku akan berada tepat di sisinya sekarang, melindunginya dari semua bahaya jika dia tidak menolak untuk membiarkanku ikut.",
  ui_story_5041_50410501_15_dialog_content = "Hawa pergi ke suatu tempat? Kemana dia pergi?",
  ui_story_5041_50410501_16_dialog_content = "Pangkalan yang terletak beberapa ratus meter jauhnya.",
  ui_story_5041_50410501_17_dialog_content = "Itu pasti jauh...",
  ui_story_5041_50410501_18_dialog_content = "Tentu saja! Anda hanya memastikan dia mendapatkan paket yang sangat penting ini!",
  ui_story_5041_50410501_19_dialog_content = "Sigh... Dia masih terlalu protektif.",
  ui_story_5041_50410501_20_dialog_content = "Aku hanya ingin merasakan pergi sendiri...",
  ui_story_5041_50410501_21_dialog_content = "Yah, menurutku adalah berkah terselubung memiliki seseorang dalam keluarga yang selalu menjagamu sepanjang waktu.",
  ui_story_5041_50410501_22_dialog_content = "Ya!",
  ui_story_5041_50410501_23_dialog_content = "Biarkan saya melihat apa yang saudara saya kirimkan kepada saya.",
  ui_story_5041_50410501_24_dialog_content = "Buku catatan, dan... untuk apa tongkat melengkung ini?",
  ui_story_5041_50410501_25_dialog_content = "Sejauh yang saya tahu, itu adalah linggis.",
  ui_story_5041_50410501_26_dialog_content = "Anda dapat mengangkat barang berat dengannya, dan menggunakannya untuk pertahanan diri dalam keadaan darurat.",
  ui_story_5041_50410501_27_dialog_content = "Jangan bilang Sinsa ingin kamu menggunakannya sebagai senjata pertahanan...",
  ui_story_5041_50410501_28_dialog_content = "Kedengarannya seperti dia ...",
  ui_story_5041_50410501_29_dialog_content = "Saya akan membaca apa yang ada di buku catatan.",
  ui_story_5041_50410501_30_dialog_content = "\"To Eve: Jangan pernah bergaul dengan orang-orang ini\"?",
  ui_story_5041_50410501_31_dialog_content = "Ini daftar nama yang panjang!",
  ui_story_5041_50410501_32_dialog_content = "Mengapa ini terdengar seperti daftar hitam?",
  ui_story_5041_50410501_33_dialog_content = "Siapa yang ada di dalamnya?",
  ui_story_5041_50410501_34_dialog_content = "Coba saya lihat... Hakim Lumopolis dengan taring hiu.",
  ui_story_5041_50410501_35_dialog_content = "Seorang peneliti Illumina menjuluki \"Pria Paruh Baya\".",
  ui_story_5041_50410501_36_dialog_content = "Pedagang Umbraton yang selalu tersenyum.",
  ui_story_5041_50410501_37_dialog_content = "Dan The Last Caelestite yang berkeliaran dengan Colossus?",
  ui_story_5041_50410501_38_option_content = "Hei, itu aku!",
  ui_story_5041_50410501_39_dialog_content = "Mengapa Sinsa menyebutku orang jahat...?",
  ui_story_5041_50410501_40_dialog_content = "Ini dia tulis...",
  ui_story_5041_50410501_41_dialog_content = "\"PlayerName bukan orang jahat, tapi ada satu hal yang harus kau perhatikan...\"",
  ui_story_5041_50410501_42_dialog_content = "\"Kecenderungan untuk meyakinkan orang lain untuk berkeliling dunia bersamanya!\"",
  ui_story_5041_50410501_43_dialog_content = "Yah, itu fakta.",
  ui_story_5041_50410501_44_dialog_content = "\"Jika Anda tidak berhati-hati, Anda akan lupa apa yang seharusnya Anda lakukan dan segera menemukan diri Anda menyelesaikan krisis di suatu tempat.\"",
  ui_story_5041_50410501_45_dialog_content = "\"Jadi hati-hati!\"",
  ui_story_5041_50410501_46_dialog_content = "Dia tidak menyebutmu orang jahat, PlayerName!",
  ui_story_5041_50410501_47_dialog_content = "Aku senang tentang itu, tapi...",
  ui_story_5041_50410501_48_dialog_content = "Itu masih tidak cocok dengan saya entah bagaimana ...",
  ui_story_5041_50410601_1_dialog_content = "Paket ekspres untuk Anda tandatangani, Nona Azure!",
  ui_story_5041_50410601_2_dialog_content = "PlayerName? Apakah Anda kurir kali ini?",
  ui_story_5041_50410601_3_dialog_content = "Anda sering dikelilingi oleh orang-orang yang begitu menarik.",
  ui_story_5041_50410601_4_dialog_content = "A-Baiklah, tolong jangan menggoda!",
  ui_story_5041_50410601_5_dialog_content = "Ini dari Zeta.",
  ui_story_5041_50410601_6_dialog_content = "Anak itu terlihat sangat mengesankan saat dia mengantarkan paket.",
  ui_story_5041_50410601_7_dialog_content = "Dia berkata-",
  ui_story_5041_50410601_8_dialog_content = "Kurir ole yang menunggangi naga putih, satu-satunya prajurit bukit pasir dengan ini mempercayakan Anda sebuah misi!",
  ui_story_5041_50410601_9_dialog_content = "Tolong kirimkan ini ke raja iblis biru yang menghuni Alam Api.",
  ui_story_5041_50410601_10_dialog_content = "Sebagai pesan tekad dari seorang pejuang!",
  ui_story_5041_50410601_11_dialog_content = "Saya menduga Anda adalah raja iblis biru yang dia bicarakan.",
  ui_story_5041_50410601_12_dialog_content = "Raja iblis lagi? Itu sepertinya menjadi peran permanen saya di kepalanya.",
  ui_story_5041_50410601_13_dialog_content = "Nah, kali ini pasti akan datang.",
  ui_story_5041_50410601_14_dialog_content = "\"Kali ini\"? Kenapa kamu sama sekali tidak terlihat terkejut?",
  ui_story_5041_50410601_15_dialog_content = "Mari kita mulai dari awal.",
  ui_story_5041_50410601_16_dialog_content = "Sejak balapan mobil itu, Zeta mulai menantangku.",
  ui_story_5041_50410601_17_dialog_content = "Dia menantang saya pada hal-hal yang berbeda hampir setiap sepuluh hari atau lebih.",
  ui_story_5041_50410601_18_dialog_content = "Hal-hal seperti batu-gunting-kertas, balapan, game aksi, dan sebagainya.",
  ui_story_5041_50410601_19_dialog_content = "Tapi dia tidak pernah menang.",
  ui_story_5041_50410601_20_dialog_content = "Kedengarannya seperti banyak ...",
  ui_story_5041_50410601_21_dialog_content = "Bermain-main dengan gadis yang menarik seperti dia juga menyenangkan bagiku.",
  ui_story_5041_50410601_22_dialog_content = "Pokoknya, tolong tandatangani paketnya!",
  ui_story_5041_50410601_23_dialog_content = "Tentu. Aku ingin tahu apa yang dia tantang padaku kali ini.",
  ui_story_5041_50410601_24_dialog_content = "<color=#e8d9bb>*Meninggal dunia*</color>",
  ui_story_5041_50410601_25_dialog_content = "Seekor bebek?",
  ui_story_5041_50410601_26_dialog_content = "Ini baru. Tapi di mana tantangannya?",
  ui_story_5041_50410601_27_dialog_content = "Saya pikir saya ingat sesuatu.",
  ui_story_5041_50410601_28_dialog_content = "Bebek itu perekam. Roy menggunakan satu untuk merekam lagu Regina sebelumnya.",
  ui_story_5041_50410601_29_dialog_content = "Biarku lihat. Anda menekan di sini, saya pikir.",
  ui_story_5041_50410601_30_dialog_content = "<color=#e8d9bb>Klik.</color>",
  ui_story_5041_50410601_31_dialog_content = "Ole blue demon lord of the Fire Realm, satu-satunya prajurit bukit pasir, menantangmu!",
  ui_story_5041_50410601_32_dialog_content = "Saya akan menunjukkan tekad saya yang teguh untuk perdamaian dunia dan kebebasan semua Aurorian.",
  ui_story_5041_50410601_33_dialog_content = "Topik dari tantangan ini adalah: Heavy metal rock!",
  ui_story_5041_50410601_34_dialog_content = "Regina, sesama pejuang bukit pasir, akan menjadi hakim dan memberikan keputusan yang adil.",
  ui_story_5041_50410601_35_dialog_content = "Jika Anda kalah, raja iblis, Anda akan menderita hukuman berat ...",
  ui_story_5041_50410601_36_dialog_content = "Bar tidak akan menyajikan minuman untuk Anda selama sebulan penuh!",
  ui_story_5041_50410601_37_dialog_content = "Namun, jika prajurit itu kalah...",
  ui_story_5041_50410601_38_dialog_content = "Saya akan menghukum diri saya yang menyedihkan dengan tidak mengkonsumsi permen lolipop selama 30 hari!",
  ui_story_5041_50410601_39_dialog_content = "Waktu tantangan diatur selama lima hari setelah surat ini dikirim. Bersiaplah untukku, raja iblis!",
  ui_story_5041_50410601_40_dialog_content = "Astaga, sepertinya kita punya tantangan nyata kali ini...",
  ui_story_5041_50410601_41_dialog_content = "Anda tidak pandai metal rock, Azure?",
  ui_story_5041_50410601_42_dialog_content = "Oh tidak, saya berbicara tentang hukuman.",
  ui_story_5041_50410601_43_dialog_content = "Satu bulan penuh tanpa minuman keras?",
  ui_story_5041_50410601_44_dialog_content = "Aku harus menunjukkan kepada anak itu betapa bagusnya aku!"
}
return config
